   const int32_t v0x = (int16_t)(src0      );
   const int32_t v0y = (int16_t)(src0 >> 16);
   const int32_t v1x = (int16_t)(src1      );
   const int32_t v1y = (int16_t)(src1 >> 16);
   dst = (v0x * v1x) + (v0y * v1y) + src2;
            _dst_val[_i].i32 = dst;
